So I can implement a swept AABB vs AABB collision.

```javascript
function getCollisionTime(ball, brick, dt) {
  const b_min_x = ball.x - ball.r;
  const b_max_x = ball.x + ball.r;
  const b_min_y = ball.y - ball.r;
  const b_max_y = ball.y + ball.r;

  const v_x = ball.vx * dt;
  const v_y = ball.vy * dt;

  let t_near_x = (brick.x - b_max_x) / v_x;
  let t_far_x = (brick.x + brick.w - b_min_x) / v_x;
  if (t_near_x > t_far_x) [t_near_x, t_far_x] = [t_far_x, t_near_x];

  let t_near_y = (brick.y - b_max_y) / v_y;
  let t_far_y = (brick.y + brick.h - b_min_y) / v_y;
  if (t_near_y > t_far_y) [t_near_y, t_far_y] = [t_far_y, t_near_y];

  const t_entry = Math.max(t_near_x, t_near_y);
  const t_exit = Math.min(t_far_x, t_far_y);

  if (t_entry > t_exit || t_exit < 0 || t_entry > 1) return null;

  return t_entry < 0 ? 0 : t_entry;
