edits.newText:
test('frame: ball bounces off top of brick', () => {
  const state = createState(1);
  // Ball moving UP, about to hit the top of a brick
  state.ball = { x: 100, y: 75, r: 7, vx: 0, vy: -200 };
  const brick = state.bricks[0]; // Top-left brick
  brick.x = 90; brick.y = 80; brick.w = 40; brick.h = 20;

  step(state, 1 / 60);

  assert.ok(state.ball.vy > 0, 'Ball should bounce DOWN after hitting the top of a brick');
  assert.equal(brick.alive, false, 'Brick should be destroyed');
});

test('frame: ball bounces off bottom of brick', () => {
  const state = createState(1);
  // Ball moving DOWN, about to hit the bottom of a brick
  state.ball = { x: 100, y: 105, r: 7, vx: 0, vy: 200 };
  const brick = state.bricks[0];
  brick.x = 90; brick.y = 80; brick.w = 40; brick.h = 20;

  step(state, 1 / 60);

  assert.ok(state.ball.vy < 0, 'Ball should bounce UP after hitting the bottom of a brick');
  assert.equal(brick.alive, false, 'Brick should be destroyed');
});

test('frame: ball bounces off left side of brick', () => {
  const state = createState(1);
  // Ball moving RIGHT, about to hit the left side of a brick
  state.ball = { x: 85, y: 90, r: 7, vx: 200, vy: 0 };
  const brick = state.bricks[0];
  brick.x = 90; brick.y = 80; brick.w = 40; brick.h = 20;

  step(state, 1 / 60);

  assert.ok(state.ball.vx < 0, 'Ball should bounce LEFT after hitting the left side of a brick');
  assert.equal(brick.alive, false, 'Brick should be destroyed');
});

test('frame: ball bounces off right side of brick', () => {
  const state = createState(1);
  // Ball moving LEFT, about to hit the right side of a brick
  state.ball = { x: 135, y: 90, r: 7, vx: -200, vy: 0 };
  const brick = state.bricks[0];
  brick.x = 90; brick.y = 80; brick.w = 40; brick.h = 20;

  step(state, 1 / 60);

  assert.ok(state.ball.vx > 0, 'Ball should bounce RIGHT after hitting the right side of a brick');
  assert.equal(brick.alive, false, 'Brick should be destroyed');
});

test('frame: ball bounces off corner (diagonal)', () => {
  const state = createState(1);
  // Ball hitting the top-left corner
  state.ball = { x: 87, y: 77, r: 7, vx: 200, vy: -200 };
  const brick = state.bricks[0];
  brick.x = 90; brick.y = 80; brick.w = 40; brick.h = 20;

  step(state, 1 / 60);

  assert.ok(state.ball.vx < 0 && state.ball.vy > 0, 'Ball should bounce back diagonally');
  assert.equal(brick.alive, false, 'Brick should be destroyed');
});

test('frame: ball does not stick to brick (push out)', () => {
  const state = createState(1);
  // Ball deeply overlapping the top of the brick
  state.ball = { x: 110, y: 78, r: 7, vx: 0, vy: -200 };
  const brick = state.bricks[0];
  brick.x = 90; brick.y = 80; brick.w = 40; brick.h = 20;

  step(state, 1 / 60);

  // After step, ball should be outside the brick
  assert.ok(!collides(state.ball, brick), 'Ball should be pushed out of the brick');
});

test('frame: tunnelling prevented', () => {
  const state = createState(1);
  // Ball moving very fast, would jump over the brick in one step
  // Position before step: (110, 70)
  // Position after step (dt=0.05, vy=1000): (110, 120)
  // Brick is at y=80, h=20. It is skipped.
  state.ball = { x: 110, y: 70, r: 7, vx: 0, vy: 1000 };
  const brick = state.bricks[0];
  brick.x = 90; brick.y = 80; brick.w = 40; brick.h = 20;

  step(state, 0.05);

  // If tunnelling is handled, the brick should be dead even if the ball is now below it.
  assert.equal(brick.alive, false, 'Brick should be destroyed even if the ball jumped over it');
});

